/**
 * DISA Application Security and Development STIG catalog
 * (compliance/DISA_ASD_STIG.json, generated by build-frameworks.mjs from the
 * DISA XCCDF) and its CWE crosswalk.
 */
import { describe, expect, it } from "vitest";
import { hasDeterministicMapping, mapFindingsDeterministic, summarizeCoverage } from "./crosswalk-mapper";
import { loadAllFrameworks } from "./pdf-parser";
import { buildFrameworkReport, complianceCacheKey, frameworkSlug, toFindingsForMapping, type FindingRow } from "./report-run";
import type { FindingForMapping } from "./llm-mapper";

const frameworks = loadAllFrameworks();
const stig = frameworks.find((f) => f.name === "DISA ASD STIG")!;
const control = (id: string) => stig.controls.find((c) => c.controlId === id)!;
const finding = (over: Partial<FindingForMapping>): FindingForMapping => ({
  id: "f1",
  title: "t",
  description: "d",
  severity: "HIGH",
  scanner: "SAST_LLM",
  cweId: null,
  ruleId: null,
  filePath: null,
  ...over,
});
const ids = (f: Partial<FindingForMapping>) => mapFindingsDeterministic([finding(f)], stig)[0].controls.map((c) => c.controlId);
const row = (id: string, cweId: string | null, severity = "HIGH"): FindingRow => ({
  id, title: id, description: "", severity, scanner: "SAST_LLM", cweId, ruleId: null, filePath: "a.ts", startLine: 1, status: "OPEN",
});

describe("DISA ASD STIG catalog", () => {
  it("is ASD STIG V6R5 from the DISA download", () => {
    expect(stig).toBeDefined();
    expect(stig.version).toBe("V6R5");
    expect(stig.revision).toBe("V6R5");
    expect(stig.source).toContain("https://dl.dod.cyber.mil/wp-content/uploads/stigs/zip/U_ASD_V6R5_STIG.zip");
    expect(frameworkSlug(stig.name)).toBe("disa-asd-stig");
  });

  it("carries every requirement in the source, by category", () => {
    // U_ASD_STIG_V6R5_Manual-xccdf.xml: 286 rules, 34 high / 230 medium / 22 low.
    expect(stig.controls).toHaveLength(286);
    const byCat = (cat: string) => stig.controls.filter((c) => c.category === cat).length;
    expect([byCat("CAT I"), byCat("CAT II"), byCat("CAT III")]).toEqual([34, 230, 22]);
  });

  it("keeps the official ids, well-formed and unique", () => {
    const unique = (xs: string[]) => new Set(xs).size === xs.length;
    for (const c of stig.controls) {
      const s = c.stig!;
      expect(c.controlId).toMatch(/^V-\d{6}$/);
      expect(s.stigId).toMatch(/^APSC-DV-\d{6}$/);
      // The Rule ID carries the Vuln ID's number: V-222607 ↔ SV-222607r961158_rule.
      expect(s.ruleId).toMatch(new RegExp(`^SV-${c.controlId.slice(2)}r\\d+_rule$`));
      expect(s.srg).toMatch(/^SRG-APP-\d{6}$/);
      expect(s.cci.length).toBeGreaterThan(0);
      for (const cci of s.cci) expect(cci).toMatch(/^CCI-\d{6}$/);
      for (const n of s.nist) expect(n).toMatch(/^[A-Z]{2}-\d+/);
      expect(c.title.length).toBeGreaterThan(10);
      expect(c.theme).not.toBe("Unassigned");
    }
    expect(unique(stig.controls.map((c) => c.controlId))).toBe(true);
    expect(unique(stig.controls.map((c) => c.stig!.stigId))).toBe(true);
    expect(unique(stig.controls.map((c) => c.stig!.ruleId))).toBe(true);
  });

  it("matches the published text for known requirements", () => {
    expect(control("V-222607")).toMatchObject({
      title: "The application must not be vulnerable to SQL Injection.",
      category: "CAT I",
      theme: "SI System and Information Integrity",
      stig: { stigId: "APSC-DV-002540", severity: "high", srg: "SRG-APP-000251", cci: ["CCI-001310"], nist: ["SI-10"] },
    });
    expect(control("V-222642")).toMatchObject({
      title: "The application must not contain embedded authentication data.",
      category: "CAT I",
      stig: { stigId: "APSC-DV-003110" },
    });
    expect(control("V-222392")).toMatchObject({ category: "CAT III", stig: { stigId: "APSC-DV-000100" } });
  });

  it("maps only requirements a code weakness can evidence", () => {
    expect(hasDeterministicMapping(stig)).toBe(true);
    expect(summarizeCoverage(stig)).toEqual({ assessable: 18, partial: 26, notAssessable: 242 });
    for (const c of stig.controls) {
      expect(c.cweMapping!.length > 0, c.controlId).toBe(c.coverage !== "not-assessable");
      expect(c.appliesTo, c.controlId).toBeUndefined();
    }
    // Process / documentation requirements stay unmapped.
    for (const id of ["V-222515", "V-222648", "V-222655", "V-222673"]) {
      expect(control(id).coverage, id).toBe("not-assessable");
    }
  });
});

describe("DISA ASD STIG crosswalk", () => {
  it("maps CWE findings to the matching requirement", () => {
    expect(ids({ cweId: "CWE-89" })).toEqual(["V-222607"]);
    expect(ids({ cweId: "79" })).toEqual(["V-222602"]);
    expect(ids({ cweId: "CWE-78" })).toEqual(["V-222604"]);
    expect(ids({ cweId: "CWE-352" })).toEqual(["V-222603"]);
    expect(ids({ cweId: "CWE-611" })).toEqual(["V-222608"]);
    expect(ids({ cweId: "CWE-120" })).toEqual(["V-222612"]);
    expect(ids({ cweId: "CWE-209" })).toEqual(["V-222610"]);
    expect(ids({ scanner: "SECRETS_PATTERN", cweId: "CWE-798" })).toEqual(["V-222642"]);
    expect(ids({ cweId: "CWE-1004" })).toEqual(["V-222575"]);
    expect(ids({ cweId: "CWE-614" })).toEqual(["V-222576"]);
    expect(ids({ cweId: "CWE-20" })).toEqual(["V-222606", "V-222609"]);
  });

  it("maps nothing without a mapped CWE", () => {
    // No activity-level rules: a finding is a gap only through its weakness.
    expect(ids({ cweId: null })).toEqual([]);
    expect(ids({ scanner: "SCA", cweId: "CWE-1357" })).toEqual([]); // licence policy
    expect(ids({ scanner: "MALICIOUS_PKG", cweId: "CWE-506" })).toEqual([]);
  });

  it("reports category and STIG ID, CAT I first", () => {
    const rows = [row("csrf", "CWE-352", "CRITICAL"), row("sqli", "CWE-89", "MEDIUM")];
    const report = buildFrameworkReport(stig, rows, mapFindingsDeterministic(toFindingsForMapping(rows), stig), "crosswalk");
    expect(report.buckets.gapsFound).toEqual([
      expect.objectContaining({ controlId: "V-222607", category: "CAT I", stigId: "APSC-DV-002540" }),
      expect.objectContaining({ controlId: "V-222603", category: "CAT II", stigId: "APSC-DV-002500" }),
    ]);
    expect(report.controlSummary.map((c) => [c.controlId, c.category])).toEqual([
      ["V-222607", "CAT I"],
      ["V-222603", "CAT II"],
    ]);
    expect(report.buckets.notCovered.find((c) => c.controlId === "V-222648")).toMatchObject({ category: "CAT II", coverage: "not-assessable" });
    expect(report.buckets.gapsFound.length + report.buckets.noIssuesDetected.length + report.buckets.notCovered.length).toBe(286);
  });

  it("leaves other frameworks' reports unchanged", () => {
    const asvs = frameworks.find((f) => f.name === "OWASP ASVS")!;
    const rows = [row("csrf", "CWE-352", "CRITICAL"), row("sqli", "CWE-89", "MEDIUM")];
    const report = buildFrameworkReport(asvs, rows, mapFindingsDeterministic(toFindingsForMapping(rows), asvs), "crosswalk");
    for (const e of [...report.buckets.gapsFound, ...report.buckets.notCovered, ...report.controlSummary]) {
      expect(e).not.toHaveProperty("category");
      expect(e).not.toHaveProperty("stigId");
    }
    // Still ordered by crit/high count, then findings.
    expect(report.buckets.gapsFound[0].criticalHighCount).toBe(1);
  });

  it("keys cached reports by STIG release", () => {
    expect(complianceCacheKey(stig, "fast", "det")).toBe("disa-asd-stig@V6R5::fast::det");
  });
});
